const request = $('Normalizar solicitud').first().json.payload;
let value = $json.output;
if (typeof value === 'string') { try { value = JSON.parse(value); } catch { value = null; } }
const actions = ['new-search', 'clarify', 'refine', 'replace-one', 'explain', 'reset'];
const filterActions = new Set(['new-search', 'refine']);
const vocabulary = { genres: ['28','35','18','53','27','878','14','10749','16','12','80','9648'], mood: ['laugh','feel','relax','tension','surprise','fear','think'], pace: ['calm','balanced','dynamic','relentless'], attention: ['easy','casual','focus','challenge'], duration: ['under-90','90-120','120-150','over-150','any'], company: ['alone','couple','friends','family'], era: ['releases','2020s','2010s','2000s','classics'], language: ['es','en','fr','it','ja','ko'], region: ['ES','US','MX','AR','FR','JP','KR'], popularity: ['popular','balanced','hidden'] };
const filterNames = [...Object.keys(vocabulary), 'minRating'];
const plain = (item) => item && typeof item === 'object' && !Array.isArray(item);
const filters = plain(value?.filtersPatch) ? value.filtersPatch : null;
const clear = Array.isArray(value?.clearFilters) ? value.clearFilters : null;
const suggestions = Array.isArray(value?.suggestedReplies) ? value.suggestedReplies : null;
const filterValueValid = (name, filterValue) => name === 'genres' ? Array.isArray(filterValue) && filterValue.length > 0 && new Set(filterValue).size === filterValue.length && filterValue.every((item) => vocabulary.genres.includes(String(item))) : name === 'minRating' ? typeof filterValue === 'number' && filterValue >= 0.5 && filterValue <= 9 && filterValue * 2 % 1 === 0 : typeof filterValue === 'string' && vocabulary[name]?.includes(filterValue);
const changes = filters && clear && (Object.keys(filters).length > 0 || clear.length > 0);
const rawTarget = value?.targetMovieId;
const target = rawTarget === 0 ? null : rawTarget;
const candidates = new Set(request.context.candidates.map((movie) => movie.tmdbId));
const valid = plain(value)
  && value.schemaVersion === 'recommendation-chat-v1'
  && value.requestId === request.requestId
  && actions.includes(value.action)
  && typeof value.reply === 'string' && value.reply.trim().length > 0 && value.reply.trim().length <= 800
  && filters && Object.entries(filters).every(([name, filterValue]) => filterNames.includes(name) && filterValueValid(name, filterValue))
  && clear && clear.length <= filterNames.length && new Set(clear).size === clear.length
  && clear.every((name) => filterNames.includes(name) && !Object.hasOwn(filters, name))
  && suggestions && suggestions.length <= 4
  && suggestions.every((text) => typeof text === 'string' && text.trim().length > 0 && text.trim().length <= 80)
  && (!changes || filterActions.has(value.action))
  && (!filterActions.has(value.action) || changes)
  && (value.action === 'replace-one' ? Number.isInteger(target) && candidates.has(target) : target === null);
if (!valid) {
  return [{ json: { schemaVersion: 'recommendation-chat-v1', requestId: request.requestId, action: 'error', reply: 'El asistente no esta disponible temporalmente.', filtersPatch: {}, clearFilters: [], targetMovieId: null, suggestedReplies: ['Reintentar'] } }];
}
return [{ json: { schemaVersion: value.schemaVersion, requestId: value.requestId, action: value.action, reply: value.reply.trim(), filtersPatch: filters, clearFilters: clear, targetMovieId: target, suggestedReplies: suggestions.map((text) => text.trim()) } }];
